from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    uniform_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    sep_counts = Counter(grid[r][0] for r in uniform_rows)
    sep_counts.update(grid[0][c] for c in uniform_cols)
    sep = sep_counts.most_common(1)[0][0]

    row_seps = {r for r in uniform_rows if grid[r][0] == sep}
    col_seps = {c for c in uniform_cols if grid[0][c] == sep}

    def chunks(n, separators):
        result, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append(list(range(start, i)))
                start = i + 1
        if start < n:
            result.append(list(range(start, n)))
        return result

    row_groups = chunks(h, row_seps)
    col_groups = chunks(w, col_seps)

    colors = Counter(
        grid[r][c]
        for rs in row_groups for cs in col_groups
        for r in rs for c in cs
    )
    background = colors.most_common(1)[0][0]

    out = []
    for rs in row_groups:
        row = []
        for cs in col_groups:
            count = sum(grid[r][c] != background for r in rs for c in cs)
            row.append(1 if count >= 2 else background)
        out.append(row)
    return out
